function generate(rand, size) {
  const length = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const pool = rand() < 0.5 ? 'aAbB' : (rand() < 0.5 ? 'xXyYzZ' : 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ');
  let s = '';
  while (s.length < length) {
    const ch = pool[Math.floor(rand() * pool.length)];
    // Repeat the same key a few times, in either case, to form runs.
    const repeat = 1 + Math.floor(rand() * 4);
    for (let j = 0; j < repeat && s.length < length; j++) s += rand() < 0.5 ? ch.toLowerCase() : ch.toUpperCase();
  }
  return [s];
}
